package solana.flipper.client;

import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.network.chat.TextColor;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Minimal MiniMessage parser supporting the subset generated by Birdflop:
 *
 *   <gradient:#hex1:#hex2:...>text</gradient>
 *   <color:#hex>text</color>  or  <#hex>text</#hex>
 *   Plain text (no tags)
 *
 * Usage:
 *   Component c = MiniMessageParser.parse("<gradient:#ff0000:#0000ff>Hello</gradient>");
 *
 * Paste the output from Birdflop's "MiniMessage" format directly into the
 * Label Text field in the config screen.
 */
public final class MiniMessageParser {

    private MiniMessageParser() {}

    // Matches <gradient:#hex1:#hex2:...>
    private static final Pattern GRADIENT_OPEN =
            Pattern.compile("<gradient((?::#[0-9a-fA-F]{6})+)>");
    // Matches </gradient>
    private static final Pattern GRADIENT_CLOSE =
            Pattern.compile("</gradient>");
    // Matches <color:#hex> or <#hex>
    private static final Pattern COLOR_OPEN =
            Pattern.compile("<(?:color:)?(#[0-9a-fA-F]{6})>");
    // Matches </color> or </#hex>
    private static final Pattern COLOR_CLOSE =
            Pattern.compile("</#?[0-9a-fA-F]{0,6}color?>");

    /**
     * Parse a MiniMessage string into a Minecraft Component.
     * Falls back to plain literal if no tags are found.
     */
    public static Component parse(String input) {
        if (input == null || input.isEmpty()) return Component.literal("");
        // Quick check — if no '<' present, just return plain text
        if (!input.contains("<")) return Component.literal(input);

        MutableComponent result = Component.empty();
        int pos = 0;
        int len = input.length();

        while (pos < len) {
            // Try gradient tag
            Matcher gm = GRADIENT_OPEN.matcher(input).region(pos, len);
            // Try color tag
            Matcher cm = COLOR_OPEN.matcher(input).region(pos, len);

            int gradStart = gm.find() ? gm.start() : Integer.MAX_VALUE;
            int colorStart = cm.find() ? cm.start() : Integer.MAX_VALUE;

            if (gradStart == Integer.MAX_VALUE && colorStart == Integer.MAX_VALUE) {
                // No more tags — append rest as plain text
                result.append(Component.literal(input.substring(pos)));
                break;
            }

            if (gradStart <= colorStart) {
                // Plain text before this tag
                if (gradStart > pos) {
                    result.append(Component.literal(input.substring(pos, gradStart)));
                }
                // Parse gradient colors from the tag
                String colorGroup = gm.group(1); // e.g. ":#ff0000:#00ff00:#0000ff"
                int[] colors = parseHexList(colorGroup);
                int afterOpen = gm.end();

                // Find closing </gradient>
                Matcher closeMatcher = GRADIENT_CLOSE.matcher(input).region(afterOpen, len);
                if (!closeMatcher.find()) {
                    // No close tag — treat rest as plain
                    result.append(Component.literal(input.substring(afterOpen)));
                    break;
                }
                String innerText = input.substring(afterOpen, closeMatcher.start());
                result.append(buildGradient(innerText, colors));
                pos = closeMatcher.end();

            } else {
                // Plain text before color tag
                if (colorStart > pos) {
                    result.append(Component.literal(input.substring(pos, colorStart)));
                }
                String hexColor = cm.group(1); // e.g. "#ff0000"
                int afterOpen = cm.end();

                // Find closing tag (</color> or </#hex>)
                Matcher closeMatcher = COLOR_CLOSE.matcher(input).region(afterOpen, len);
                // Also accept </color>
                Matcher closeColor = Pattern.compile("</color>")
                        .matcher(input).region(afterOpen, len);

                int closePos;
                int closeEnd;
                int p1 = closeMatcher.find() ? closeMatcher.start() : Integer.MAX_VALUE;
                int p2 = closeColor.find()   ? closeColor.start()   : Integer.MAX_VALUE;
                if (p1 <= p2) {
                    closePos = p1;
                    closeEnd = closeMatcher.end();
                } else if (p2 < Integer.MAX_VALUE) {
                    closePos = p2;
                    closeEnd = closeColor.end();
                } else {
                    // No close — color rest of string
                    closePos = len;
                    closeEnd = len;
                }

                String innerText = input.substring(afterOpen, closePos);
                int rgb = Integer.parseInt(hexColor.substring(1), 16);
                MutableComponent colored = Component.literal(innerText)
                        .withStyle(Style.EMPTY.withColor(TextColor.fromRgb(rgb)));
                result.append(colored);
                pos = closeEnd;
            }
        }

        return result;
    }

    // ── Gradient builder ───────────────────────────────────────────────────

    /**
     * Splits text into per-character components, each with an interpolated color.
     */
    private static Component buildGradient(String text, int[] colors) {
        if (text.isEmpty()) return Component.empty();
        if (colors.length == 0) return Component.literal(text);
        if (colors.length == 1) {
            return Component.literal(text)
                    .withStyle(Style.EMPTY.withColor(TextColor.fromRgb(colors[0])));
        }

        MutableComponent result = Component.empty();
        int n = text.length();

        for (int i = 0; i < n; i++) {
            float t = (n == 1) ? 0f : (float) i / (n - 1);
            int color = interpolateGradient(colors, t);
            result.append(Component.literal(String.valueOf(text.charAt(i)))
                    .withStyle(Style.EMPTY.withColor(TextColor.fromRgb(color))));
        }
        return result;
    }

    /**
     * Interpolates across multiple color stops.
     * t = 0.0 → first color, t = 1.0 → last color.
     */
    private static int interpolateGradient(int[] colors, float t) {
        int segments = colors.length - 1;
        float scaled = t * segments;
        int seg = Math.min((int) scaled, segments - 1);
        float local = scaled - seg;

        int c1 = colors[seg];
        int c2 = colors[seg + 1];

        int r = lerp((c1 >> 16) & 0xFF, (c2 >> 16) & 0xFF, local);
        int g = lerp((c1 >>  8) & 0xFF, (c2 >>  8) & 0xFF, local);
        int b = lerp((c1      ) & 0xFF, (c2      ) & 0xFF, local);
        return (r << 16) | (g << 8) | b;
    }

    private static int lerp(int a, int b, float t) {
        return Math.round(a + (b - a) * t);
    }

    /** Parses ":#hex1:#hex2:..." into an int array of RGB values. */
    private static int[] parseHexList(String s) {
        // s looks like ":#ced9ef:#Cfc7fb:#e2c6ee"
        String[] parts = s.split(":");
        List<Integer> list = new ArrayList<>();
        for (String p : parts) {
            p = p.trim();
            if (p.startsWith("#") && p.length() == 7) {
                try {
                    list.add(Integer.parseInt(p.substring(1), 16));
                } catch (NumberFormatException ignored) {}
            }
        }
        return list.stream().mapToInt(Integer::intValue).toArray();
    }
}
